mapper.select:
select * from ( select sm.ID, sm.BEAD_CODE, sm.MACHINE_CODE, sm.LINE_TYPE, sm.JOB_TYPE, sm.REMARK, sm.IS_DELETE, sm.CREATE_BY, sm.CREATE_TIME, sm.UPDATE_BY, sm.UPDATE_TIME, m.machine_name from T_TQ_SPECIFY_MACHINE sm left join T_TQ_MACHINE_INFO m on sm.machine_code = m.machine_code where sm.IS_DELETE = '0' and m.IS_DELETE = '0'
and INSTR(sm.BEAD_CODE, #{beadCode}) > 0
and sm.MACHINE_CODE = #{machineCode}
and sm.LINE_TYPE = #{lineType}
and sm.JOB_TYPE = #{jobType}
order by sm.create_time desc ) t
